# Python program to solve the assignment problem by
# trying every one-to-one assignment of workers to jobs

def assign(cost, worker, used, current, best):
    n = len(cost)
    if worker == n:
        return min(best, current)
    for job in range(n):
        if not used[job]:
            used[job] = True
            best = assign(cost, worker + 1, used, current + cost[worker][job], best)
            used[job] = False
    return best

