    n = len(cost)
    used = [False] * n
    print(assign(cost, 0, used, 0, float("inf")))

# Python program to generate all permutations of a list
# by inserting each element at every position

def permutations(items):
    result = [[]]
    for x in items:
        new_result = []
        for p in result:
            for pos in range(len(p) + 1):
                new_result.append(p[:pos] + [x] + p[pos:])
        result = new_result
    return result

