    for p in permutations(items):
        print(p)

# Python program to count Hamiltonian paths by checking
# every ordering of the vertices

def count_hamiltonian_paths(adj, order, l, n):
    if l == n:
        for i in range(n - 1):
            if adj[order[i]][order[i + 1]] == 0:
                return 0
        return 1
    total = 0
    for i in range(l, n):
        order[l], order[i] = order[i], order[l]
        total += count_hamiltonian_paths(adj, order, l + 1, n)
        order[l], order[i] = order[i], order[l]
    return total

