    n = len(adj)
    order = list(range(n))
    print(count_hamiltonian_paths(adj, order, 0, n))

# Python program to print all permutations of a list
# by passing the remaining characters down

def permute(chars, prefix):
    if not chars:
        print("".join(prefix))
        return
    for i in range(len(chars)):
        permute(chars[:i] + chars[i + 1:], prefix + [chars[i]])

